#!/usr/bin/env bash
# mado round 12 — after-measurement script. Run from the lane root with REV=<commit> and
# MADO_VERIFY_HARNESS set; prints every command before its output (`set -x` style, by hand).
set -u
REV="${REV:?set REV}"
S=corpus/SOURCES.md
run() { printf '$ %s\n' "$1"; bash -c "$1"; printf '\n'; }
echo "# round-12 after-measurements at $REV, $(date -u +%FT%TZ); worktree dirty paths: $(git status --porcelain | wc -l) (SCORECARD.md results + after.txt are written after this run)"
echo "## C1 calibration"
run "grep -cE '^[0-9]+\. .*lessons/' corpus/QUALITY.md"
run "grep -cE '^[0-9]+\. ' corpus/QUALITY.md"
run "grep -E '^[0-9]+\. ' corpus/QUALITY.md | while IFS= read -r l; do n=\${l%%.*}; paths=\$(grep -oE 'lessons/[A-Za-z0-9._-]+\.md' <<<\"\$l\" | sort -u); [ -n \"\$paths\" ] || continue; ok=1; for p in \$paths; do [ -e \"corpus/\$p\" ] || ok=0; done; for m in \$(grep -oE '#mistakes M[0-9]+' <<<\"\$l\" | grep -oE 'M[0-9]+'); do grep -qE \"^\| \$m \|\" corpus/lessons/round-12.md || ok=0; done; [ \$ok = 1 ] && echo \$n; done | wc -l"
run "grep -E '^[0-9]+\. .*lessons/round-12.md#mistakes' corpus/QUALITY.md | wc -l"
echo "## C2 freshness"
run "bash tools/mado-verify.sh --no-live | awk '\$3==\"FAIL\"||\$3==\"UNKNOWN\"' | wc -l"
run "bash tools/mado-verify.sh --no-live | awk '\$3==\"PASS\"' | wc -l"
run "grep -c '^> Erratum (round 12' SKILL.md"
run "grep -c '^## Errata (round 12)' SKILL.md"
echo "## freshness (a), observational"
run "for f in corpus/knowledge/*.md; do head -n 15 \"\$f\" | grep -q '^source:' && head -n 15 \"\$f\" | grep -q '^verified-at:' && head -n 15 \"\$f\" | grep -q '^recheck:' && echo \"\$f\"; done | wc -l"
run "ls corpus/knowledge/*.md | wc -l"
echo "## C3 coverage"
run "for f in corpus/knowledge/*.md; do head -n 15 \"\$f\" | grep -qE '^source:.*\bS[0-9]{3,}\b' && echo \"\$f\"; done | wc -l"
run "for f in corpus/knowledge/*.md; do h=\$(head -n 15 \"\$f\"); grep -qE '^source:.*\bS[0-9]{3,}\b' <<<\"\$h\" || continue; grep -oE '^covers: U[1-7]' <<<\"\$h\"; done | sort -u"
run "awk -F'|' '/^\|[[:space:]]*S[0-9]{3,}[[:space:]]*\|/ {i=\$2;s=\$9;u=\$12; gsub(/[[:space:]]/,\"\",i); gsub(/[[:space:]]/,\"\",s); gsub(/^[[:space:]]+|[[:space:]]+\$/,\"\",u); print i\"\t\"s\"\t\"u}' $S > /tmp/mado-r12-rows.tsv; while IFS=\$'\t' read -r i s u; do [ \"\$s\" = mined ] || continue; for p in \${u//,/ }; do grep -qw \"\$i\" \"\$p\" || echo \"row \$i used-by \$p does not cite it\"; done; done < /tmp/mado-r12-rows.tsv; for f in corpus/knowledge/*.md; do src=\$(head -n 15 \"\$f\" | grep -E '^source:'); [ -n \"\$src\" ] || continue; for i in \$(grep -oE '\bS[0-9]{3,}\b' <<<\"\$src\" | sort -u); do awk -F'\t' -v i=\$i -v f=\"\$f\" '\$1==i && \$2==\"mined\" && index(\$3,f) {ok=1} END{if(!ok) print \"entry \"f\" cites \"i\" without a mined row naming it\"}' /tmp/mado-r12-rows.tsv; done; done; echo join-done"
echo "## SOURCES contract census (SOURCES-CONTRACT-v1.md:66-80, verbatim)"
run "grep -cE '^\|[[:space:]]*S[0-9]{3,}[[:space:]]*\|' $S"
run "awk -F'|' '/^\|[[:space:]]*S[0-9][0-9][0-9]+[[:space:]]*\|/ && NF!=13 {n++} END{print n+0}' $S"
run "awk -F'|' '/^\|[[:space:]]*S[0-9][0-9][0-9]+[[:space:]]*\|/ {t=\$5; gsub(/[[:space:]]/,\"\",t); n[t]++} END{for(k in n) printf \"%s=%d \", k, n[k]; print \"\"}' $S"
run "awk -F'|' '/^\|[[:space:]]*S[0-9][0-9][0-9]+[[:space:]]*\|/ {s=\$9; gsub(/[[:space:]]/,\"\",s); n[s]++} END{for(k in n) printf \"%s=%d \", k, n[k]; print \"\"}' $S"
run "awk -F'|' '/^\|[[:space:]]*S[0-9][0-9][0-9]+[[:space:]]*\|/ {i=\$2; gsub(/[[:space:]]/,\"\",i); print i}' $S | sort | uniq -d; echo dup-check-done"
run "awk -F'|' '/^\|[[:space:]]*S[0-9][0-9][0-9]+[[:space:]]*\|/ && NF==13 {i=\$2;k=\$4;t=\$5;s=\$9; gsub(/[[:space:]]/,\"\",i); gsub(/[[:space:]]/,\"\",k); gsub(/[[:space:]]/,\"\",t); gsub(/[[:space:]]/,\"\",s); if (t !~ /^[ABC]\$/) print \"tier\", i, t; if (s !~ /^(queued|mined|rejected)\$/) print \"status\", i, s; if (k !~ /^(spec|docs|paper|code|tool|dataset|talk|book|community|own-work)\$/) print \"kind\", i, k; if (t==\"A\" && k==\"community\") print \"tier-inflation\", i}' $S; echo enum-check-done"
run "awk -F'|' '/^\|[[:space:]]*S[0-9][0-9][0-9]+[[:space:]]*\|/ && NF==13 {s=\$9; gsub(/[[:space:]]/,\"\",s); if (s==\"mined\") {n=split(\$12, a, /[,;]/); for (j=1;j<=n;j++) {p=a[j]; gsub(/^[[:space:]]+|[[:space:]]+\$/,\"\",p); if (p!=\"\" && p!=\"—\") print p}}}' $S | while read -r p; do [ -e \"\$p\" ] || echo \"missing: \$p\"; done; echo used-by-check-done"
echo "## harm watch"
run "git show $REV:SCORECARD.md | awk '/^\`\`\`bash\$/{f=1;next} /^\`\`\`\$/{if(f){exit}} f' > /tmp/mado-r12-counter.sh; sha256sum < /tmp/mado-r12-counter.sh; REV=$REV bash -s < /tmp/mado-r12-counter.sh; echo exit=\$?"
run "bash tools/mado-verify.sh --selftest | tail -1"
run "bash tools/mado-verify.sh | tail -2"
run "bash tools/mado-verify.sh --regression | grep '^MADO_REGRESSION'"
run "sha256sum tools/mado-verify.sh; wc -lc tools/mado-verify.sh"
